questionvariables.text:
hits(L,s,tol) := length(sublist(L, lambda([v], is(abs(v-s) <= tol))));
matchset(L,S,tol) := is(length(L) = length(S)) and every(lambda([s], is(hits(L,s,tol) = 1)), S);
allgenuine(L,S,tol) := every(lambda([v], some(lambda([s], is(abs(v-s) <= tol)), S)), L);
validate_angles(ex) := if (setp(ex) or listp(ex)) and every(lambda([v], numberp(ev(v,simp))), if setp(ex) then listify(ex) else ex) then "" else "Type the angles as numbers inside curly brackets, separated by commas, for example {30, 150}. Do not type the degree sign.";
r1(v) := float(floor(10*v+1/2)/10);
ang1(v) := block([r], r: floor(10*v+1/2), if integerp(r/10) then string(r/10) else string(float(r/10)));
setraw(L) := if L = [] then "\\{\\,\\}" else sconcat("\\{", simplode(map(lambda([v], sconcat(ang1(v), "^\\circ")), sort(L)), ", "), "\\}");
degraw(v) := sconcat(ang1(v), "^\\circ");
setstr(L) := sconcat("\\(", setraw(L), "\\)");
angc(v) := block([al], al: float(acos(v)*180/%pi), if abs(al) < 1e-9 then [0,360] elseif abs(al-180) < 1e-9 then [180] else [al, 360-al]);
angs(v) := block([al], al: float(asin(v)*180/%pi), if abs(al) < 1e-9 then [0,180,360] elseif abs(al-90) < 1e-9 then [90] elseif abs(al+90) < 1e-9 then [270] elseif al > 0 then [al, 180-al] else [180-al, 360+al]);
qroots(A,B,C) := if A = 0 then (if B = 0 then [] else [-C/B]) elseif B^2-4*A*C < 0 then [] else [(-B-sqrt(B^2-4*A*C))/(2*A), (-B+sqrt(B^2-4*A*C))/(2*A)];
inrange(L) := sublist(L, lambda([v], is(abs(float(v)) <= 1+1e-12)));
uniqf(L) := unique(map(lambda([v], float(floor(10000*v+1/2)/10000)), L));
nice(v) := block([r], r: floor(1000*v+1/2)/1000, if integerp(r) then r else float(r));
res2(v) := block([r], r: floor(100*v+1/2)/100, if integerp(r) then string(r) else string(float(r)));
tm(n, s) := if n = 0 then "" elseif n = 1 then sconcat(" + ", s) elseif n = -1 then sconcat(" - ", s) elseif n > 0 then sconcat(" + ", string(n), s) else sconcat(" - ", string(-n), s);
tc(n) := if n = 0 then "" elseif n > 0 then sconcat(" + ", string(n)) else sconcat(" - ", string(-n));
lead(n, s) := if n = 1 then s elseif n = -1 then sconcat("-", s) else sconcat(string(n), s);
/* Design: table of values for a trigonometric graph. Entry: 1 sine / 0 cosine, a, b, phase cc (never c: learners do not type c here, but the chapter keeps c free), the five asked x-values. Source: original. */
L: [[1,2,1,15,[60,120,210,270,330]],[0,3,1,-30,[0,90,150,240,300]],[1,3,1,75,[30,90,150,240,300]],[0,2,1,60,[30,90,180,240,330]],
 [1,4,1,-60,[0,90,150,210,330]],[0,1.5,1,45,[0,90,150,240,330]],[1,2,2,0,[15,60,105,150,165]],[0,3,2,30,[0,45,75,120,165]],
 [1,5,1,-45,[0,90,165,225,300]],[0,4,1,30,[30,60,120,210,300]]];
ix: 1+rand(10);
fs: L[ix][1]; a: L[ix][2]; b: L[ix][3]; cc: L[ix][4]; xs: L[ix][5];
fname: if fs = 1 then "\\sin" else "\\cos";
fd(t) := if fs = 1 then sin(%pi*t/180) else cos(%pi*t/180);
fr(t) := if fs = 1 then sin(t) else cos(t);
r2(v) := float(floor(100*v+1/2)/100);
yv: makelist(float(a*fd(b*xs[k]+cc)), k, 1, 5);
yrad: makelist(float(a*fr(b*xs[k]+cc)), k, 1, 5);
ynoa: makelist(float(fd(b*xs[k]+cc)), k, 1, 5);
stp: if b = 1 then 30 else 15;
xmax: if b = 1 then 360 else 180;
xg: makelist(stp*k, k, 0, xmax/stp);
yg: map(lambda([t], r2(float(a*fd(b*t+cc)))), xg);
argd: sconcat(if b = 1 then "x" else sconcat(string(b), "x"), tc(cc));
fdisp: sconcat(if a = 1 then "" else string(a), fname, if cc = 0 then sconcat(" ", argd) else sconcat("(", argd, "^\\circ)"));
inner: makelist(b*xs[k]+cc, k, 1, 5);
lets: ["(a)","(b)","(c)","(d)","(e)"];
ycell: map(lambda([t], if member(t, xs) then lets[sublist_indices(xs, lambda([u], is(u = t)))[1]] else dispdp(r2(float(a*fd(b*t+cc))),2)), xg);

feedbackvariables.text:
al: [ans1, ans2, ans3, ans4, ans5];
cellok: makelist(is(abs(al[k] - yv[k]) <= 0.00501), k, 1, 5);
nrad: length(sublist(makelist(k, k, 1, 5), lambda([k], is(abs(al[k] - r2(yrad[k])) <= 0.00501) or is(abs(al[k] - yrad[k]) <= 0.00501))));
nnoa: length(sublist(makelist(k, k, 1, 5), lambda([k], is(abs(al[k] - r2(ynoa[k])) <= 0.00501) or is(abs(al[k] - ynoa[k]) <= 0.00501))));
wrongx: sublist(makelist(k, k, 1, 5), lambda([k], not cellok[k]));
wrongxs: map(lambda([k], xs[k]), wrongx);
wrongstr: simplode(map(lambda([k], sconcat(string(xs[k]), "^\\circ")), wrongx), ",\\ ");
w1: if wrongx = [] then 1 else wrongx[1];
